const prefix = "qmqz-web|" + self.registration.scope + "|";
const cacheName = prefix + version;
const root = new URL(self.registration.scope);
const indexUrl = new URL("index.html", root).href;
const urls = new Set(build.files.map(file => new URL(file.url, root).href));

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(cacheName);
    try {
      // Limit concurrent large reads. The current release stays active until every batch succeeds.
      for (let i = 0; i < build.files.length; i += 4) {
        const batch = build.files.slice(i, i + 4).map(file =>
          new Request(new URL(file.url, root), { cache: "reload", integrity: file.integrity }));
        await cache.addAll(batch);
      }
    } catch (error) {
      await caches.delete(cacheName);
      throw error;
    }
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const previous = (await caches.keys()).filter(key => key.startsWith(prefix) && key !== cacheName);
    await Promise.all(previous.map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", event => {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);
  url.search = "";
  const key = url.href === root.href ? indexUrl : url.href;
  if (!urls.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(cacheName);
    return await cache.match(key) || fetch(event.request);
  })());
});
